parameters.jsCode:
const text = $input.first().json.candidates[0].content.parts[0].text;
const parsed = JSON.parse(text);
const triggerData = $('1. Terima File Telegram').item;

return {
  json: {
    ...parsed,
    chat_id: triggerData.json.message.chat.id,
    file_name: triggerData.binary.data.fileName || ('bukti_' + Date.now() + '.jpg'),
    file_mime: triggerData.binary.data.mimeType || 'image/jpeg',
    file_base64: triggerData.binary.data.data
  }
};

